INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, output_unit, clause_reference, description, verification_status, verification_quote)
SELECT w.id, 'M12001-07-D1', 'restrisiko_max_code = max_rows(risiko_zeilen, restrisiko_code)', ARRAY['risiko_zeilen']::text[], 'restrisiko_max_code', NULL, '§6.3.4, Tab. 23; §6.3.5, Tab. 25', 'Plan 3: höchstes Restrisiko über die Arbeitshilfe-C-Zeilen (Code 1 = Sehr niedrig … 5 = Sehr hoch nach TAB23; Zeilen unter "moderat" behalten ihr Ausgangsrisiko); Ziel "auf ein sehr niedriges oder niedriges Risikoniveau reduziert" (L2061) = Code ≤ 2; CR-014 / restrisiko_niveau STAGED (m1200_1-G-5 / -D-1).', 'imported_unverified', 'In Fällen, in denen im Rahmen der Risikobewertung ein moderates oder hohes Risikoniveau bestimmt wurde, sind durch das Risikomanagement entsprechende vorsorgende Maßnahmen zu etablieren, durch die alle identifizierten Risiken auf ein sehr niedriges oder niedriges Risikoniveau reduziert werden können. Ein Risikoniveau, das als sehr hoch eingestuft wird, ist nach bisherigen Erfahrungen mit Wasserwiederverwendungsanwendungen, die keine Trinkwasserqualität bereitstellen, eher ungewöhnlich (Asano et al. 2007; ISO 20426 2108; MoHR et al. 2020). Für Risiken, die als sehr niedrig oder niedrig eingestuft werden, sind in der Regel keine weitergehenden Anforderungen erforderlich, und das für den Menschen akzeptable Risikoniveau gilt als eingehalten. — Ergreifung von Vorsorgemaßnahmen erforderlich. Im zweiten Teil der Risikobewertung werden die risikomindernden Vorsorgemaßnahmen beschrieben und das sich daraus ergebende Schadensausmaß inklusive Erwägungsgrund und die Eintrittswahrscheinlich inklusive Erwägungsgrund eingetragen. Anschließend erfolgt nochmals die Risikobewertung zur Ermittlung des Restrisikos (siehe Tabelle 23 und Tabelle 24).'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'M12001-07' AND s.code = 'DWA-M-1200-1'
ON CONFLICT (worksheet_template_id, equation_number) DO NOTHING;
