SELECT w.id, 'M12001-16-D1', 'anwendungsbereich_count_calc = count_rows(flaechenverzeichnis)', ARRAY['flaechenverzeichnis']::text[], 'anwendungsbereich_count_calc', NULL, '§7.3 (Art. 6 Abs. 3 EU-WasserWVVO)', 'Plan 3: Anzahl vollständiger Flächen im Flächenverzeichnis ("inkl. eines Flächenverzeichnisses der zu bewässernden Flächen", L2465); ersetzt das manuelle anwendungsbereich_count (M12001-08) — STAGED (m1200_1-C-2); CR-015 auf >= 1 STAGED (m1200_1-G-8).', 'imported_unverified', 'I Aussagen zu der Güteklasse des aufbereiteten Wassers und dem Verwendungszweck bzw. den Verwendungszwecken (Kulturen, Nutzungen etc.), für den bzw. die das aufbereitete Wasser gemäß Anhang I zu genehmigen ist, den potenziellen Verbrauchsstellen linkl. eines Flächenverzeichnisses der zu bewässernden Flächen), den Aufbereitungseinrichtungen und der geschätzten jährlichen Menge des aufzubereitenden Wassers, dem Zustand sowie der Nutzung der Flächen einschließlich der Bewässerungsmethode;'
