INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, output_unit, clause_reference, description, verification_status, verification_quote)
SELECT w.id, 'M12001-09-D1', 'compliance_quote_calc = count_rows(routineproben, ok == 1) * 100 / count_rows(routineproben, relevant == 1)', ARRAY['routineproben']::text[], 'compliance_quote_calc', '%', '§5.2', 'Plan 3: Anteil der Routineproben, die den Tab.-8-Wert ihrer Klasse einhalten (Legionella strikt "<", sonst "≤"; Proben eines Parameters ohne Grenzwert zählen weder im Zähler noch im Nenner; 100 = Prozent; keine Probe mit Grenzwert ⇒ unentscheidbar, nie 0); "in mindestens 90 % der Proben eingehalten" (L1143 / L1145) = routine_min_share_pct; CR-008 / compliance_quote_pct STAGED (m1200_1-G-7 / -C-2); die maximale Abweichungsgrenze (eine log10-Stufe / 100 %) ist nicht kodiert (Residuum).', 'imported_unverified', 'In Anlehnung an die EU-WasserWVVO müssen die vorgegebenen Werte für E. coli, Legionella spp. und intestinale Nematoden in Tabelle 8 in mindestens $90 \%$ der Proben eingehalten werden. Keiner der Werte der Proben darf die maximale Abweichungsgrenze von einer $\log _{10}$-Stufe für den vorgegebenen Wert für E. coli und Legionella spp. und $100 \%$ des vorgegebenen Werts für intestinale Nematoden überschreiten. — Die vorgegebenen Werte für $\mathrm{BSB}_{5}$, AFS und Trübung bei Güteklasse A bis C müssen in mindestens $90 \%$ der Proben eingehalten werden. Keiner der Werte der Proben darf die maximale Abweichungsgrenze von $100 \%$ des vorgegebenen Werts überschreiten.'
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE w.code = 'M12001-09' AND s.code = 'DWA-M-1200-1'
ON CONFLICT (worksheet_template_id, equation_number) DO NOTHING;
